(function seedFilterDemoDates(){
  const pad=n=>String(n).padStart(2,'0');
  const fmt=d=>`${pad(d.getDate())}.${pad(d.getMonth()+1)}.${d.getFullYear()}`;
  const base=new Date();base.setHours(12,0,0,0);
  const weekStart=new Date(base);weekStart.setDate(base.getDate()-base.getDay());
  const dateAt=i=>{const d=new Date(weekStart);d.setDate(weekStart.getDate()+i);return fmt(d)};
  const todayIndex=base.getDay();
  const byId=Object.fromEntries(events.map(e=>[e.id,e]));
  [[1,todayIndex],[2,todayIndex],[21,todayIndex],[4,0],[5,1],[6,2],[7,3],[35,4],[22,5],[28,6]].forEach(([id,i])=>{if(byId[id])byId[id].date=dateAt(i)});
})();
