function normalizeFavorites(list){return[...new Set((list||[]).map(Number).filter(id=>Number.isFinite(id)&&events.some(e=>e.id===id)))]}
function toast(msg){const t=document.getElementById('toast');t.textContent=msg;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),1800)}
function setAccountTab(tab){const t=tab||'tickets';document.querySelectorAll('.account-nav [data-account-tab]').forEach(x=>x.classList.toggle('active',x.dataset.accountTab===t));document.querySelectorAll('.account-panel').forEach(x=>x.classList.add('hidden'));const panel=document.getElementById(t+'Panel');if(panel)panel.classList.remove('hidden')}
function setEventTab(tab){const t=tab||'dates';document.querySelectorAll('.event-tab').forEach(x=>x.classList.toggle('active',x.dataset.tab===t));document.querySelectorAll('.tab-panel').forEach(x=>x.classList.toggle('active',x.dataset.panel===t))}
function isHomeRoute(){return(location.hash.replace('#','')||'home').split('/')[0]==='home'}
function lockHomeScrollTop(){if(!isHomeRoute())return;const snap=()=>{window.scrollTo(0,0);if(document.documentElement)document.documentElement.scrollTop=0;if(document.body)document.body.scrollTop=0};snap();requestAnimationFrame(()=>{snap();requestAnimationFrame(snap)});[0,50,100,250].forEach(ms=>setTimeout(snap,ms))}
window.lockHomeScrollTop=lockHomeScrollTop;
function route(id,fromHash){const raw=(id||'home').replace(/^#/,''),parts=raw.split('/'),screen=parts[0]||'home',tab=parts[1];document.querySelectorAll('.screen').forEach(s=>s.classList.remove('active'));const target=document.getElementById(screen)||document.getElementById('home');target.classList.add('active');if(screen==='account')setAccountTab(tab||'tickets');if(screen==='event'){setEventTab(tab||'dates');syncEventPage(getEventById(activeEventId));renderShowDates();renderRelated();startFullPresaleTicker()}if(screen==='seats'){if(typeof window.resetSeatsFlow==='function')window.resetSeatsFlow();else if(typeof window.initSeats==='function')window.initSeats()}if(screen==='seats'||screen==='cart'||screen==='login'||screen==='details'||screen==='payment'){syncFlowHeroes(getEventById(activeEventId));syncEventPosters(getEventById(activeEventId))}if(screen==='success')setTimeout(playSuccessIcon,40);const next=tab?screen+'/'+tab:screen;if(location.hash.replace(/^#/,'')!==next){const url=location.pathname+location.search+'#'+next;try{history[fromHash?'replaceState':'pushState'](null,'',url)}catch(_){location.hash=next}}if(screen==='home')lockHomeScrollTop();else if(!fromHash)window.scrollTo({top:0,behavior:'smooth'});else window.scrollTo(0,0)}
function playSuccessIcon(){const icon=document.querySelector('#success lord-icon');if(!icon)return;const clone=icon.cloneNode(true);icon.replaceWith(clone)}
function eventImage(e){return e&&e.image?e.image:`assets/events/${e&&e.id?e.id:1}.jpg`}
function eventGalleryImages(e){const ev=e||{id:1};const id=Number(ev.id)||1;const imgs=[eventImage(ev)];for(let step=1;imgs.length<3;step++){const nid=((id-1+step)%48)+1;const src=`assets/events/${nid}.jpg`;if(!imgs.includes(src))imgs.push(src)}return imgs.slice(0,3)}
function getPosterCount(root){return Number(root.dataset.posterCount)||0}
function getPosterIndex(root){return Number(root.dataset.posterIndex)||0}
function setPosterIndex(root,index){root.dataset.posterIndex=String(index)}
function syncPosterDots(root,index){const dots=[...root.querySelectorAll('.event-poster-dot')];dots.forEach((d,i)=>{const on=i===index;d.classList.toggle('is-active',on);d.setAttribute('aria-selected',String(on))})}
function stopPosterAutoplay(root){if(root._posterTimer){clearInterval(root._posterTimer);root._posterTimer=null}}
function startPosterAutoplay(root){stopPosterAutoplay(root);const total=getPosterCount(root);if(total<=1)return;if(window.matchMedia('(prefers-reduced-motion: reduce)').matches)return;root._posterTimer=setInterval(()=>{if(root.classList.contains('is-dragging')||root.matches(':hover'))return;applyEventPosterIndex(root,getPosterIndex(root)+1)},3000)}
function applyEventPosterIndex(root,index,animate){const slides=[...root.querySelectorAll('.event-poster-slide:not(.is-clone)')];const total=Math.max(1,getPosterCount(root)||slides.length);const target=((index%total)+total)%total;const current=getPosterIndex(root);setPosterIndex(root,target);slides.forEach((slide,i)=>{const on=i===target;if(animate===false){slide.style.transition='none';slide.classList.toggle('is-active',on);void slide.offsetWidth;slide.style.transition=''}else{slide.classList.toggle('is-active',on)}slide.setAttribute('aria-hidden',String(!on))});syncPosterDots(root,target);}
function syncEventPosterSlider(e){const ev=e||getEventById(activeEventId)||{id:1};const imgs=eventGalleryImages(ev);const alt=ev.title||'תמונת מופע';document.querySelectorAll('.event-poster-slider').forEach(root=>{stopPosterAutoplay(root);root.setAttribute('aria-label',`גלריית ${alt}`);let track=root.querySelector('.event-poster-track');let dots=root.querySelector('.event-poster-dots');if(!track){root.innerHTML=`<div class="event-poster-viewport"><div class="event-poster-track"></div></div><div class="event-poster-dots" role="tablist" aria-label="ניווט תמונות"></div>`;track=root.querySelector('.event-poster-track');dots=root.querySelector('.event-poster-dots')}const n=imgs.length;root.dataset.posterCount=String(n);if(track){track.innerHTML=imgs.map((src,i)=>`<div class="event-poster-slide${i?'':' is-active'}" role="img" aria-hidden="${i===0?'false':'true'}" aria-label="${alt} — תמונה ${i+1} מתוך ${n}" style="background-image:url('${src}')"></div>`).join('')}if(dots)dots.innerHTML=imgs.map((_,i)=>`<button type="button" class="event-poster-dot${i?'':' is-active'}" role="tab" aria-selected="${i===0?'true':'false'}" aria-label="תמונה ${i+1}" data-poster-index="${i}"></button>`).join('');applyEventPosterIndex(root,0,false);startPosterAutoplay(root)})}
function bindEventPosterSlider(root){if(!root||root.dataset.bound)return;root.dataset.bound='1';let dragging=false,startX=0,deltaX=0;const endDrag=()=>{if(!dragging)return;dragging=false;root.classList.remove('is-dragging');const idx=getPosterIndex(root);if(Math.abs(deltaX)>40)applyEventPosterIndex(root,deltaX<0?idx+1:idx-1);else applyEventPosterIndex(root,idx);deltaX=0;startPosterAutoplay(root)};root.addEventListener('pointerdown',e=>{if(e.button!==0)return;if(e.target.closest('.event-poster-dot'))return;dragging=true;startX=e.clientX;deltaX=0;root.classList.add('is-dragging');stopPosterAutoplay(root);try{root.setPointerCapture(e.pointerId)}catch(_){}});root.addEventListener('pointermove',e=>{if(!dragging)return;deltaX=e.clientX-startX});root.addEventListener('pointerup',endDrag);root.addEventListener('pointercancel',endDrag);root.addEventListener('click',e=>{const dot=e.target.closest('[data-poster-index]');if(!dot)return;const next=Number(dot.dataset.posterIndex);if(!Number.isFinite(next))return;applyEventPosterIndex(root,next);startPosterAutoplay(root)});root.addEventListener('mouseenter',()=>stopPosterAutoplay(root));root.addEventListener('mouseleave',()=>{if(!dragging)startPosterAutoplay(root)});document.addEventListener('visibilitychange',()=>{if(document.hidden)stopPosterAutoplay(root);else startPosterAutoplay(root)})}
function initEventPosterSlider(){document.querySelectorAll('.event-poster-slider').forEach(bindEventPosterSlider)}
function syncEventPosters(e){const ev=e||getEventById(activeEventId)||{id:1};const src=eventImage(ev);const alt=ev.title||'תמונת מופע';document.querySelectorAll('.event-poster:not(.event-poster-slider)').forEach(el=>{el.textContent='';el.setAttribute('role','img');el.setAttribute('aria-label',alt);el.style.backgroundImage=`url('${src}')`});syncEventPosterSlider(ev);initEventPosterSlider()}

function cardLocation(e){return [e.venue,e.city].filter(Boolean).join(', ')}function cardDateLabel(e){const raw=String(e.date||'');if(!raw)return'';if(/יום\s|שני|שלישי|רביעי|חמישי|שישי|שבת|ראשון/.test(raw))return raw;const m=raw.match(/(\d{1,2})\.(\d{1,2})\.(\d{4})/);if(!m)return raw;const dt=new Date(+m[3],+m[2]-1,+m[1]);if(Number.isNaN(dt.getTime()))return raw;const days=['יום ראשון','יום שני','יום שלישי','יום רביעי','יום חמישי','יום שישי','יום שבת'];return `${days[dt.getDay()]}, ${m[1].padStart(2,'0')}.${m[2].padStart(2,'0')}.${m[3]}`}function nearestShowDateLabel(e){if(!e)return'';if(Array.isArray(e.dates)&&e.dates.length){const now=Date.now()-86400000;const parsed=e.dates.map(x=>{const raw=String(x&&x.d||'');const m=raw.match(/(\d{1,2})\.(\d{1,2})\.(\d{4})/);if(!m)return{label:raw,t:Number.POSITIVE_INFINITY};const t=new Date(+m[3],+m[2]-1,+m[1]).getTime();return{label:raw,t:Number.isNaN(t)?Number.POSITIVE_INFINITY:t}}).filter(x=>x.label);parsed.sort((a,b)=>a.t-b.t);const upcoming=parsed.find(x=>x.t>=now)||parsed[0];return upcoming?upcoming.label:''}return cardDateLabel(e)||String(e.date||'')}function cardDateRangeLabel(e){const keys=collectEventDateKeys(e);const fmt=k=>{const[y,m,d]=k.split('-');return `${d}.${m}.${y}`};let start='',end='';if(keys.length>=2){start=fmt(keys[0]);end=fmt(keys[keys.length-1])}else if(keys.length===1){start=fmt(keys[0]);const[y,m,d]=keys[0].split('-').map(Number);const dt=new Date(y,m-1,d+10);end=`${String(dt.getDate()).padStart(2,'0')}.${String(dt.getMonth()+1).padStart(2,'0')}.${dt.getFullYear()}`}else{const raw=String(e&&e.date||'12.08.2026');const m=raw.match(/(\d{1,2})\.(\d{1,2})\.(\d{4})/);if(m){start=`${m[1].padStart(2,'0')}.${m[2].padStart(2,'0')}.${m[3]}`;const dt=new Date(+m[3],+m[2]-1,+m[1]+10);end=`${String(dt.getDate()).padStart(2,'0')}.${String(dt.getMonth()+1).padStart(2,'0')}.${dt.getFullYear()}`}else{start='12.08.2026';end='22.08.2026'}}return `<strong class="card-date-emph">החל מ-</strong>${start} <strong class="card-date-emph">עד</strong> ${end}`}
function cardAvailabilityLevel(e){if(e&&(e.availability==='כניסה חופשית'||Number(e.price)===0&&e.availability&&e.availability.includes('חופש')))return'free';const id=Number(e&&e.id)||0;return id%2===0?'low':'high'}
function cardAvailabilityLabel(e){const level=cardAvailabilityLevel(e);if(level==='free')return e.availability||'כניסה חופשית';return level==='low'?'זמינות נמוכה':'זמינות גבוהה'}
function cardAvailabilityHtml(e){const level=cardAvailabilityLevel(e);const label=cardAvailabilityLabel(e);if(level==='free')return `<div class="event-availability">${label}</div>`;return `<div class="event-availability is-${level}"><i class="card-avail-dot is-${level}" aria-hidden="true"></i><span>${label}</span></div>`}
