function favoriteBtnHtml(e){const active=favorites.includes(e.id);return `<button class="favorite-btn ${active?'active':''}" data-favorite-id="${e.id}" aria-label="מועדפים"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8l1.1 1.1L12 21.3l7.8-7.8 1.1-1.1a5.5 5.5 0 0 0-.1-7.8Z"/></svg></button>`}
function card(e){const full=isFullPresaleActive(e);const presaleBlock=full?cardPresaleBlock(e):'';const btnLabel=full?'להשארת פרטים':'לפרטים ורכישה';const ribbon=full?'<span class="presale-ribbon">המכירה בקרוב</span>':'';const btnCls=full?'btn primary card-presale-btn':'btn primary';const openAttr=full?` data-open-event="${e.id}" tabindex="0" role="link"`:'';return `<article class="event-card${full?' is-full-presale':''}"${openAttr} aria-label="${e.title}"><div class="event-media">${ribbon}${favoriteBtnHtml(e)}<img src="${eventImage(e)}" alt="" loading="lazy"></div><div class="event-body"><h3>${e.title}</h3>${full?'':cardFactsHtml(e)}${full?'':cardAvailabilityHtml(e)}${presaleBlock}<div class="event-footer">${cardFooterPriceHtml(e,full)}<button class="${btnCls}" data-open-event="${e.id}">${btnLabel}</button></div></div></article>`}
function flipCard(e,opts){const full=isFullPresaleActive(e);const presaleBlock=full?cardPresaleBlock(e):'';const btnLabel=full?'להשארת פרטים':'לפרטים ורכישה';const ribbon=full?'<span class="presale-ribbon">המכירה בקרוב</span>':'';const btnCls=full?'btn primary card-presale-btn':'btn primary';const openAttr=full?` data-open-event="${e.id}" tabindex="0" role="link"`:'';const frontDate=opts&&opts.showFrontDate?cardDateRangeLabel(e):'';const frontDateHtml=(!full&&frontDate)?`<p class="event-card-front-date">${frontDate}</p>`:'';return `<article class="event-card event-card-flip${full?' is-full-presale':''}"${openAttr} aria-label="${e.title}"><div class="event-card-inner"><div class="event-card-face event-card-front">${ribbon}<img src="${eventImage(e)}" alt="" loading="lazy" draggable="false"><div class="event-card-front-title"><h3>${e.title}</h3>${frontDateHtml}</div></div><div class="event-card-face event-card-back">${favoriteBtnHtml(e)}<div class="event-body"><h3>${e.title}</h3>${full?'':cardFactsHtml(e)}${full?'':cardAvailabilityHtml(e)}${presaleBlock}<div class="event-footer">${cardFooterPriceHtml(e,full)}<button class="${btnCls}" data-open-event="${e.id}">${btnLabel}</button></div></div></div></div></article>`}
function getCardLayout(){const ok=v=>v==='all-flip'||v==='all-simple'||v==='popular'||v==='popular-special'||v==='popular-special-flip';const fromDom=document.body?.dataset?.cardLayout;if(ok(fromDom))return fromDom;try{const raw=localStorage.getItem('ticketsThemeOptions');if(raw){const v=JSON.parse(raw)?.cardLayout;if(ok(v))return v}}catch(_){}return'popular'}
function renderHome(){const arrowSvg='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M9 5l7 7-7 7" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"/></svg>';const starSvg='<svg class="section-star" viewBox="0 0 24 24" aria-hidden="true"><path fill="currentColor" d="M12 2.8l2.4 6.1 6.6.4-5.1 4.2 1.7 6.4L12 16.6 6.4 19.9l1.7-6.4L3 9.3l6.6-.4L12 2.8z"/></svg>';const layout=getCardLayout();document.getElementById('homeSections').innerHTML=sections.map((name,index)=>{const isPopular=name==='מופעים פופולריים';const title=isPopular?'הכי פופולריים':name;const useCoverflow=(layout==='popular-special'||layout==='popular-special-flip')&&isPopular;const useFlip=layout==='all-flip'||layout==='popular-special-flip'||(layout!=='all-simple'&&isPopular);const catKey=sectionCategoryKey[name]||'all';let source=events.filter(e=>e.category===name);if(isPopular&&source.length<12){const seen=new Set(source.map(e=>e.id));for(const e of events){if(seen.has(e.id))continue;source.push(e);seen.add(e.id);if(source.length>=12)break}}if(!source.length)return'';const items=source.slice(0,isPopular?12:8);const cards=items.map(e=>useFlip?flipCard(e,{showFrontDate:true}):card(e)).join('');let flipClass='';if(useCoverflow)flipClass=' popular-coverflow-carousel popular-flip-carousel';else if(useFlip)flipClass=isPopular?' popular-flip-carousel flip-carousel':' flip-carousel';const useBokeh=isPopular&&document.body.classList.contains('popular-bokeh-on');const allBtnIconColors=(document.body.classList.contains('theme-palette-light')&&!useBokeh)?'primary:#1d104a,secondary:#1d104a':'primary:#ffffff,secondary:#ffffff';return `<section class="section ${index%2?'alt':''}${useCoverflow?' popular-coverflow-section':''}${useFlip?' flip-cards-section':''}${isPopular?' popular-flip-section':''}${useBokeh?' popular-bokeh-section':''}">${useBokeh?'<canvas class="popular-bokeh-canvas" aria-hidden="true"></canvas>':''}<div class="container carousel-shell${useCoverflow?' coverflow-shell':''}"><div class="section-header"><button type="button" class="heading-icon section-title-link" data-category="${catKey}" aria-label="לעמוד ${title}">${starSvg}<h2>${title}</h2></button><button class="btn section-all-btn" data-category="${catKey}"><span class="section-all-btn-label">למופעים בקטגוריה</span><lord-icon class="section-all-btn-icon" src="https://cdn.lordicon.com/nhvkplrv.json" trigger="loop" state="hover-scale" colors="${allBtnIconColors}" stroke="regular" style="width:28px;height:28px" aria-hidden="true"></lord-icon></button></div><button type="button" class="carousel-side-arrow prev" data-carousel-prev aria-label="הקודם">${arrowSvg}</button><div class="event-carousel${flipClass}">${cards}</div><button type="button" class="carousel-side-arrow next" data-carousel-next aria-label="הבא">${arrowSvg}</button></div></section>`}).join('');initPopularBokeh()}
function initPopularBokeh(){
  const reduce=window.matchMedia('(prefers-reduced-motion:reduce)').matches;
  document.querySelectorAll('.popular-bokeh-section').forEach(section=>{
    const canvas=section.querySelector('.popular-bokeh-canvas');
    if(!canvas)return;
    if(canvas._bokeh && typeof canvas._bokeh.destroy==='function')canvas._bokeh.destroy();
    if(!document.body.classList.contains('popular-bokeh-on'))return;
    const ctx=canvas.getContext('2d');
    if(!ctx)return;
    let raf=0,ro=null,bokehs=[];
    const hues=[335,330,320,280,260,250];
    class Bokeh{
      constructor(w,h){
        this.size=Math.random()*90+55;
        this.x=Math.random()*w;
        this.y=Math.random()*h;
        this.H=hues[Math.floor(Math.random()*hues.length)];
        this.S=Math.floor(Math.random()*35+55);
        this.L=Math.floor(Math.random()*28+28);
        this.angleX=Math.random()*4-2;
        this.angleY=Math.random()*4-2;
      }
      update(w,h){
        this.x+=Math.cos(this.angleX)*0.55;
        this.y+=Math.sin(this.angleY)*0.55;
        if(this.x>w+this.size)this.x=-this.size;
        if(this.x<-this.size)this.x=w+this.size;
        if(this.y>h+this.size)this.y=-this.size;
        if(this.y<-this.size)this.y=h+this.size;
        this.angleX+=0.0018;
        this.angleY+=0.0018;
      }
      draw(){
        ctx.beginPath();
        ctx.arc(this.x,this.y,this.size,0,Math.PI*2);
        ctx.fillStyle=`hsla(${this.H},${this.S}%,${this.L}%,.72)`;
        ctx.fill();
      }
    }
    function resize(){
      const rect=section.getBoundingClientRect();
      const dpr=Math.min(window.devicePixelRatio||1,2);
      const w=Math.max(1,Math.floor(rect.width));
      const h=Math.max(1,Math.floor(rect.height));
      canvas.width=Math.floor(w*dpr);
      canvas.height=Math.floor(h*dpr);
      canvas.style.width=w+'px';
      canvas.style.height=h+'px';
      ctx.setTransform(dpr,0,0,dpr,0,0);
      const count=reduce?8:14;
      bokehs=Array.from({length:count},()=>new Bokeh(w,h));
      if(reduce){
        ctx.clearRect(0,0,w,h);
        bokehs.forEach(b=>b.draw());
      }
    }
    function frame(){
      const w=canvas.clientWidth,h=canvas.clientHeight;
      ctx.clearRect(0,0,w,h);
      bokehs.forEach(b=>{b.update(w,h);b.draw()});
      raf=requestAnimationFrame(frame);
    }
    function destroy(){
      cancelAnimationFrame(raf);
      if(ro)ro.disconnect();
      canvas._bokeh=null;
    }
    resize();
    if(!reduce)raf=requestAnimationFrame(frame);
    if(typeof ResizeObserver!=='undefined'){
      ro=new ResizeObserver(()=>resize());
      ro.observe(section);
    }
    canvas._bokeh={destroy};
  });
}
function carouselScrollState(track){const max=Math.max(0,track.scrollWidth-track.clientWidth),eps=4,sl=track.scrollLeft;if(max<=eps)return{atStart:true,atEnd:true};if(sl<=0)return{atStart:sl>=-eps,atEnd:sl<=-max+eps};return{atStart:sl>=max-eps,atEnd:sl<=eps}}
function syncCarouselArrows(shell){const track=shell.querySelector('.event-carousel');if(!track)return;const prev=shell.querySelector('[data-carousel-prev]'),next=shell.querySelector('[data-carousel-next]');const{atStart,atEnd}=carouselScrollState(track);if(prev){prev.disabled=atStart;prev.setAttribute('aria-disabled',String(atStart))}if(next){next.disabled=atEnd;next.setAttribute('aria-disabled',String(atEnd))}}
let eventsShown=12,eventsRangeFilter='all',eventsCategoryFilter='all';

function parseEventDate(e){const m=String(e?.date||'').match(/(\d{1,2})\.(\d{1,2})\.(\d{4})/);if(!m)return null;const d=new Date(+m[3],+m[2]-1,+m[1]);return Number.isNaN(d.getTime())?null:d}
function startOfDay(d){return new Date(d.getFullYear(),d.getMonth(),d.getDate())}
function eventMatchesRange(e,range){if(!range||range==='all')return true;const raw=parseEventDate(e);if(!raw)return false;const d=startOfDay(raw),now=startOfDay(new Date());if(range==='today')return d.getTime()===now.getTime();if(range==='week'){const weekStart=new Date(now);weekStart.setDate(now.getDate()-now.getDay());const weekEnd=new Date(weekStart);weekEnd.setDate(weekStart.getDate()+6);return d>=weekStart&&d<=weekEnd}if(range==='month')return d.getMonth()===now.getMonth()&&d.getFullYear()===now.getFullYear();return true}
function eventsCatalog(){let list=events.filter(e=>eventMatchesRange(e,eventsRangeFilter));const meta=categoryMeta[eventsCategoryFilter];if(meta&&eventsCategoryFilter!=='all')list=list.filter(meta.match);return list}
function syncEventsPageHeader(){const meta=categoryMeta[eventsCategoryFilter]||categoryMeta.all;const h1=document.querySelector('#events .page-hero h1');const crumb=document.querySelector('#events .page-hero [aria-current="page"]');if(h1)h1.textContent=meta.label;if(crumb)crumb.textContent=meta.label}
function openCategory(key){eventsCategoryFilter=categoryMeta[key]?key:'all';eventsShown=12;syncEventsPageHeader();renderEvents();route('events')}
function renderEvents(){const catalog=eventsCatalog();const list=catalog.slice(0,Math.min(eventsShown,catalog.length));const layout=getCardLayout();const useFlip=layout==='all-flip'||layout==='popular-special-flip';const grid=document.getElementById('eventsGrid');if(grid){grid.classList.toggle('events-flip-grid',useFlip);grid.innerHTML=list.length?list.map(e=>useFlip?flipCard(e,{showFrontDate:true}):card(e)).join(''):'<p class="events-empty">לא נמצאו מופעים בטווח שנבחר.</p>'}const countEl=document.getElementById('resultsCount');if(countEl)countEl.textContent=list.length;const wrap=document.getElementById('loadMoreEvents')?.closest('.load-more-wrap');if(wrap)wrap.classList.toggle('hidden',eventsShown>=catalog.length||catalog.length===0);syncEventsPageHeader()}
function loadMoreEvents(){const catalog=eventsCatalog();if(eventsShown>=catalog.length)return;eventsShown=Math.min(catalog.length,eventsShown+4);renderEvents()}
function loadAllEvents(){const catalog=eventsCatalog();if(eventsShown>=catalog.length)return;eventsShown=catalog.length;renderEvents()}
function setEventsRangeFilter(range){eventsRangeFilter=range||'all';eventsShown=12;document.querySelectorAll('#eventsDateFilters .filter-chip').forEach(btn=>btn.classList.toggle('active',btn.dataset.eventsRange===eventsRangeFilter));renderEvents()}
function renderRelated(){const current=getEventById(activeEventId);const others=events.filter(e=>e.id!==activeEventId);const same=[...others.filter(e=>current&&(e.category===current.category||e.genre===current.genre)),...others.filter(e=>!current||(e.category!==current.category&&e.genre!==current.genre))];const seen=new Set();const list=[];for(const e of same){if(seen.has(e.id))continue;seen.add(e.id);list.push(e);if(list.length>=4)break}document.getElementById('relatedEvents').innerHTML=list.map(card).join('')}
