function ticketMarkup(){const tickets=[{title:'עידן רייכל',meta:'12.08.2026 · 21:00 · אמפי שוני',seat:'יציע A · שורה 4 · מושב 12',url:'tickets/idan-raichel.pdf'},{title:'אדיר מילר',meta:'18.08.2026 · 20:30 · היכל התרבות',seat:'אולם · שורה 8 · מושב 24',url:'tickets/adir-miller.pdf'}];return tickets.map(t=>{const abs=new URL(t.url,location.href).href;const wa=`https://wa.me/?text=${encodeURIComponent(`הנה הכרטיס שלך למופע ${t.title}: ${abs}`)}`;return `<article class="digital-ticket"><div class="ticket-main"><span class="badge" style="position:static;display:inline-block">פעיל</span><h2>${t.title}</h2><p>${t.meta}</p><strong>${t.seat}</strong></div>${qrMarkup()}<div class="ticket-actions"><a class="btn ticket-btn ticket-btn-primary" href="${t.url}" target="_blank" rel="noopener noreferrer" aria-label="פתיחת כרטיס PDF"><img src="assets/icons/pdf.svg" alt=""><span>פתח כרטיס PDF</span></a><a class="btn ticket-btn ticket-btn-secondary" href="${wa}" target="_blank" rel="noopener noreferrer" aria-label="שיתוף הכרטיס ב־WhatsApp"><img src="assets/icons/whatsapp.svg" alt=""><span>שתף ב־WhatsApp</span></a></div></article>`}).join('')}
