function showAvailLevel(x){if(!x)return'';if(x.sold||x.s==='אזלו הכרטיסים')return'sold';if(x.presale)return'presale';if(x.queue||x.low||x.s==='זמינות נמוכה')return'low';if(x.s==='זמינות גבוהה'||x.s==='זמין'||x.s==='המכירה נפתחה'||x.action==='seats'||x.action==='queue')return'high';return''}function showAvailabilityDot(x){const level=showAvailLevel(x);if(!level)return'';const labels={sold:'אזלו הכרטיסים',presale:'פתיחת מכירה בקרוב',low:'זמינות נמוכה',high:'זמינות גבוהה'};const label=labels[level]||'';const disabled=level==='presale'?' is-disabled':'';return `<span class="show-avail-dot is-${level}${disabled}" title="${label}" aria-hidden="true"></span>`}function showRowMainHtml(x){const p=parseShowRowParts(x);return `<div class="show-row-main">${showAvailabilityDot(x)}<strong class="show-row-date">${p.shortDate}</strong><span class="show-row-when">${p.dayTime}</span><span class="show-row-venue">${p.venue}</span></div>`}
function collectEventDateKeys(e){const keys=[];const push=label=>{const k=parseShowDateKey(label);if(k)keys.push(k)};if(e&&e.isFullPresale===true&&Array.isArray(e.dates)&&e.dates.length){e.dates.forEach(x=>push(x&&x.d))}else{try{buildRegularShowDates().forEach(x=>push(x.d))}catch(_){} if(!keys.length&&e&&Array.isArray(e.dates))e.dates.forEach(x=>push(x&&x.d)); if(!keys.length&&e&&e.date)push(e.date)} return[...new Set(keys)].sort()}
function eventDateRangeLabel(e){const keys=collectEventDateKeys(e);const fmt=k=>{const[y,m,d]=k.split('-');return `${d}/${m}/${y}`};if(!keys.length)return'12/08/2026 - 22/08/2026';if(keys.length===1)return fmt(keys[0]);return `${fmt(keys[0])} - ${fmt(keys[keys.length-1])}`}
function eventHeroMetaHtml(e){const range=eventDateRangeLabel(e||null);const chip=(icon,text)=>text?`<li class="event-hero-meta-item"><img src="assets/icons/${icon}.svg" alt="" aria-hidden="true"><span>${text}</span></li>`:'';return `<ul class="event-hero-meta-list">${chip('calendar',range)}</ul>`}function eventMetaLine(e){if(!e)return defaultEventHero.meta;const loc=cardLocation(e);const date=cardDateLabel(e)||e.date||'';return [date,e.time,loc].filter(Boolean).join(' · ')}
