function getShowDatesQtyMode(){let m=document.body.dataset.showDatesQty||'medium';if(m!=='medium'&&m!=='calendar'&&m!=='default')m='medium';if(m==='default'&&typeof window.matchMedia==='function'&&window.matchMedia('(max-width:960px)').matches)return'medium';return m}
function getAvailableShowDatesCount(){const m=getShowDatesQtyMode();if(m==='medium')return 6;return 2}
function padShowDate(n){return String(n).padStart(2,'0')}
function showDateLabelAt(offsetDays){const days=['ראשון','שני','שלישי','רביעי','חמישי','שישי','שבת'];const start=new Date(2026,7,12);const dt=new Date(start);dt.setDate(start.getDate()+offsetDays);return `${days[dt.getDay()]}, ${padShowDate(dt.getDate())}.${padShowDate(dt.getMonth()+1)}.${dt.getFullYear()}`}
function expandHighShowDates(count){const venues=['אמפי שוני · בנימינה · 21:00','היכל התרבות · תל אביב · 20:30','בנייני האומה · ירושלים · 21:15','היכל התרבות · חיפה · 20:00'];const out=[];for(let i=0;i<count;i++)out.push({d:showDateLabelAt(i),m:venues[i%venues.length],s:'זמינות גבוהה',action:'seats'});return out}
