(function initSearchFilterIcons(){
  const form=document.getElementById('homeSearch');
  if(!form)return;
  const loc=document.getElementById('searchLocation');
  const cat=document.getElementById('searchCategory');
  const display=document.getElementById('dateRangeDisplay');
  const dateField=form.querySelector('.date-search-field');
  const locField=loc&&loc.closest('.search-field');
  const catField=cat&&cat.closest('.search-field');
  const defaultDate='בכל תאריך';
  const defaultLoc=(loc&&loc.options[0]&&loc.options[0].textContent)||'כל הארץ';
  const defaultCat=(cat&&cat.options[0]&&cat.options[0].textContent)||'כל הקטגוריות';
  function sync(){
    if(locField&&loc){
      const v=(loc.options[loc.selectedIndex]&&loc.options[loc.selectedIndex].textContent||loc.value||'').trim();
      locField.classList.toggle('is-active',!!v&&v!==defaultLoc);
    }
    if(catField&&cat){
      const v=(cat.options[cat.selectedIndex]&&cat.options[cat.selectedIndex].textContent||cat.value||'').trim();
      catField.classList.toggle('is-active',!!v&&v!==defaultCat);
    }
    if(dateField&&display){
      const v=(display.textContent||'').trim();
      dateField.classList.toggle('is-active',!!v&&v!==defaultDate);
    }
  }
  loc&&loc.addEventListener('change',sync);
  cat&&cat.addEventListener('change',sync);
  // date presets / custom updates rewrite display text — observe + hook clicks
  if(display){
    const mo=new MutationObserver(sync);
    mo.observe(display,{characterData:true,childList:true,subtree:true});
  }
  form.querySelectorAll('.date-preset').forEach(btn=>btn.addEventListener('click',()=>setTimeout(sync,0)));
  const from=document.getElementById('dateFrom'),to=document.getElementById('dateTo');
  from&&from.addEventListener('change',()=>setTimeout(sync,0));
  to&&to.addEventListener('change',()=>setTimeout(sync,0));
  sync();
  window.ticketsSyncSearchFilterIcons=sync;
})();

